  "title": {
    "template": "title",
    "heading": "Fractions of amounts",
    "lead": "Recall: 24 counters shared equally between 4 groups. How many in each?",
    "picture": null
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "One equal part",
      "lead": "The denominator tells us how many equal groups to make.",
      "points": [
        {"label": "Unit fraction", "text": "Its numerator is 1: we take one group."},
        "⅕ of 20 = 20 ÷ 5 = 4"
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twenty counters shared into five equal groups to show one fifth.",
        "alt": "Twenty counters are arranged in five rings, each containing four counters.",
        "title": null,
        "total": 20,
        "groups": 5,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "equation-hero",
      "heading": "Find ⅙ of 24",
      "lead": null,
      "formula": "⅙ of 24 = 24 ÷ 6",
      "points": [
        "Make 6 equal groups.",
        "Each group has 4: ⅙ of 24 = 4."
      ],
      "figure": {
        "kind": "equal-groups",
        "shows": "Twenty-four counters shared into six equal groups.",
        "alt": "Six rings each contain four counters, making twenty-four counters altogether.",
        "title": null,
        "total": 24,
        "groups": 6,
        "layout": "rings",
        "show_count": "each",
        "unknown": false
      }
    },
    {
      "template": "practice",
      "heading": "Find one equal part",
      "questions": [
        "Find ⅙ of 30.",
        "Find ¼ of 36.",
        "Find ⅛ of 56. Explain why you divide by 8."
      ],
      "instruction": "Write the division and the answer.",
      "picture": null
    },
    {
      "template": "equation-hero",
      "heading": "Find ⅚ of 24",
      "lead": null,
      "formula": "⅚ of 24 = (24 ÷ 6) × 5",
      "points": [
        "One sixth: 24 ÷ 6 = 4",
        "Five sixths: 4 × 5 = 20"
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "Five of six equal parts of twenty-four are selected.",
        "alt": "A bar of twenty-four has six equal parts of four, with five parts shaded.",
        "title": null,
        "bars": [
          {
            "label": "24",
            "whole": 24,
            "parts": 6,
            "values": null,
            "shaded": 5,
            "unknown": "none",
            "unit": null
          }
        ],
        "combined": false
      }
    },
    {
      "template": "practice",
      "heading": "Find several equal parts",
      "questions": [
        "Find ⅚ of 30.",
        "Find ¾ of 36.",
        "Find ⅜ of 56."
      ],
      "instruction": "Find one part first. Then find the parts you need.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "Which number tells us to divide?",
      "lead": "Sam says: “⅔ of 18 is 18 ÷ 2 × 3 = 27.”",
      "points": [
        "Thirds means 3 equal parts: 18 ÷ 3 = 6.",
        "Take 2 parts: 6 × 2 = 12.",
        "⅔ is less than a whole, so 27 cannot be right."
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "Two of three equal parts of eighteen correct Sam's calculation.",
        "alt": "A bar of eighteen is split into three parts of six, with two parts shaded.",
        "title": null,
        "bars": [
          {
            "label": "18",
            "whole": 18,
            "parts": 3,
            "values": null,
            "shaded": 2,
            "unknown": "none",
            "unit": null
          }
        ],
        "combined": false
      }
    },
    {
      "template": "hinge",
      "heading": "Choose the calculation",
      "stem": "Which calculation finds ⅜ of 40?",
      "options": [
        "40 ÷ 3 × 8",
        "40 ÷ 8",
        "40 ÷ 8 × 3",
        "40 ÷ 8 × 5"
      ],
      "correct": 3
    },
    {
      "template": "equation-hero",
      "heading": "A money problem",
      "lead": "Mia has £35. She spends ⅗ of it on a book. How much does the book cost?",
      "formula": "⅗ of £35 = (£35 ÷ 5) × 3",
      "points": [
        "One fifth: £35 ÷ 5 = £7",
        "Three fifths: £7 × 3 = £21",
        "The book costs £21."
      ],
      "figure": {
        "kind": "bar-model",
        "shows": "Three of five equal parts of thirty-five pounds give the book's cost.",
        "alt": "Thirty-five pounds is split into five parts of seven pounds; three parts are shaded.",
        "title": null,
        "bars": [
          {
            "label": "Money",
            "whole": 35,
            "parts": 5,
            "values": null,
            "shaded": 3,
            "unknown": "none",
            "unit": "£"
          }
        ],
        "combined": false
      }
    },
    {
      "template": "practice",
      "heading": "Solve the word problems",
      "questions": [
        "Leo has £45. He spends ⅗ of it on a game. How much does the game cost?",
        "A ribbon is 48 cm long. Aisha cuts off ¼ of it. How long is the piece?",
        "A jug holds 800 ml of juice. Ben pours out ⅜ of it. How much does he pour out?"
      ],
      "instruction": "Write a calculation and an answer with its unit.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Use fractions in new situations",
      "questions": [
        "A wildlife camera takes 72 photos. ⅝ show foxes. How many photos show foxes?",
        "A 96 km route has water stops along its first ⅙. How many kilometres is that?",
        "Stretch: Jo has £40; Ali has £56. Jo spends ¾ and Ali spends ⅝. Who spends more, and by how much?"
      ],
      "instruction": "Solve each problem. Explain your reasoning for the stretch.",
      "picture": null
    }
  ]
}
